<template>
	<scroll-view scroll-y class="page-container" @scroll="handleScroll" :style="{
	      paddingTop: navHeight + 'px',
	      height: 'calc(100vh - ' + navHeight + 'px)'
	    }" :scroll-top="scrollTop">
		<custom-nav :title="pageTitle" :isHomePage="false" :scrollTop="scrollTop" />
		<view class="content" >
		<!-- 顶部搜索和切换区域 -->
		<view class="header">
			<view class="search-box">
				<view class="filter-btn" @tap="showFilter">
					<text class="filter-text">筛选</text>
					<text class="filter-icon">▼</text>
				</view>
				<input type="text" class="search-input" :placeholder="'搜索医院'" v-model="searchText" @input="onSearch" />
			</view>
		</view>

		<!-- 筛选弹出层 -->
		<view class="filter-mask" v-if="showFilterPanel" @tap="hideFilter">
			<view class="filter-panel" @tap.stop>
				<view class="filter-header">
					<text>筛选条件</text>
					<text class="close-btn" @tap="hideFilter">×</text>
				</view>

				<!-- 医院筛选条件 -->
				<view v-if="currentType === 'hospital'" class="filter-content">
					<view class="filter-section location-section">
						<view class="section-title">地理位置</view>
						<view class="location-container">
							<!-- 省份列表 -->
							<scroll-view class="location-column" scroll-y>
								<view v-for="province in locations.provinces" :key="province"
									:class="['location-item', selectedProvince === province ? 'active' : '']"
									@tap="selectProvince(province)">
									{{province}}
								</view>
							</scroll-view>

							<!-- 城市列表 -->
							<scroll-view class="location-column" scroll-y>
								<view v-for="city in availableCities" :key="city"
									:class="['location-item', selectedCity === city ? 'active' : '']"
									@tap="selectCity(city)">
									{{city}}
								</view>
							</scroll-view>

							<!-- 区域列表 -->
							<scroll-view class="location-column" scroll-y>
								<view v-for="district in availableDistricts" :key="district"
									:class="['location-item', selectedDistrict === district ? 'active' : '']"
									@tap="selectDistrict(district)">
									{{district}}
								</view>
							</scroll-view>
						</view>
					</view>
					<view class="filter-section">
						<view class="section-title">医院等级</view>
						<view class="filter-options">
							<view v-for="level in hospitalLevels" :key="level"
								:class="['filter-option', selectedLevel === level ? 'active' : '']"
								@tap="selectLevel(level)">
								{{level}}
							</view>
						</view>
					</view>
					<view class="filter-section">
						<view class="section-title">医院类型</view>
						<view class="filter-options">
							<view v-for="type in hospitalTypes" :key="type"
								:class="['filter-option', selectedType === type ? 'active' : '']"
								@tap="selectType(type)">
								{{type}}
							</view>
						</view>
					</view>
				</view>

				<!-- 筛选按钮 -->
				<view class="filter-buttons">
					<view class="reset-btn" @tap="resetFilter">重置</view>
					<view class="confirm-btn" @tap="confirmFilter">确定</view>
				</view>
			</view>
		</view>

		<!-- 医院列表内容 -->
		<view class="hospital-content" v-if="currentType === 'hospital'">
		  <view class="hospital-grid">
		    <view class="hospital-card" v-for="hospital in filteredHospitals" :key="hospital._id"
		      @tap="handleHospitalTap(hospital)">
		      <!-- 修改图片部分，添加默认图片 -->
		      <image src="/static/images/more/hospital.png" mode="aspectFill"></image>
		      <view class="hospital-info">
		        <text class="hospital-name">{{hospital.name}}</text>
		        <view class="type-level-container">
		          <text class="hospital-level">{{hospital.level}}</text>
		          <text class="hospital-type">{{hospital.type}}</text>
		        </view>
		        <text class="hospital-address">{{hospital.address.city}}{{hospital.address.detail}}</text>
		      </view>
		    </view>
		  </view>
		</view>
		</view>
	</scroll-view>
</template>

<script>
	export default {
		data() {
			return {
				pageTitle:"医院列表",
				navHeight: 0, // 添加导航栏高度存储
				currentType: 'hospital',
				searchText: '',
				hospitals: [],
				filteredHospitals: [], 
					// 更多医院数据
				showFilterPanel: false,
				hospitalLevels: ['三级甲等', '三级乙等', '二级甲等', '二级乙等'],
				hospitalTypes: ['国营','股份制'],
				selectedLevel: '',
				selectedType: '',
				selectedGroup: '',
				filterConditions: {
					hospital: {
						province:'',
						city:'',
						level: '',
						type: ''
					},
					disease: {
						group: ''
					}
				},
				locations: {
					provinces: ['北京', '上海', '广东省', '江苏省'],
					cities: {
						'北京': ['北京市'],
						'上海': ['上海市'],
						'广东省': ['广州市', '深圳市', '珠海市'],
						'江苏省': ['南京市', '苏州市', '无锡市'],
					},
					districts: {
						'北京市': ['东城区', '西城区', '朝阳区', '海淀区'],
						'广州市': ['天河区', '越秀区', '海珠区', '白云区'],
					}
				},
				selectedProvince: '',
				selectedCity: '',
				selectedDistrict: '',
				fromPage: null // 用于记录来源页面
			}
		},
		computed: {
			availableCities() {
				return this.selectedProvince ? this.locations.cities[this.selectedProvince] : []
			},
			availableDistricts() {
				return this.selectedCity ? this.locations.districts[this.selectedCity] : []
			}
		},
		methods: {
			switchType(type) {
				this.currentType = type
			},
			onSearch() {
			        if (!this.searchText) {
			            this.filteredHospitals = this.hospitals; // 如果没有搜索关键词，显示所有医院
			        } else {
			            this.filteredHospitals = this.hospitals.filter(hospital => {
			                return hospital.name.toLowerCase().includes(this.searchText.toLowerCase());
			            });
			        }
			    },
			showFilter() {
				this.showFilterPanel = true
			},
			hideFilter() {
				this.showFilterPanel = false
			},
			selectLevel(level) {
				this.selectedLevel = this.selectedLevel === level ? '' : level
			},
			selectType(type) {
				this.selectedType = this.selectedType === type ? '' : type
			},
			selectGroup(group) {
				this.selectedGroup = this.selectedGroup === group ? '' : group
			},
			resetFilter() {
				this.selectedLevel = ''
				this.selectedType = ''
				this.selectedGroup = ''
				this.selectedProvince = ''
				this.selectedCity = ''
				this.selectedDistrict = ''
			},
			confirmFilter() {
				if (this.currentType === 'hospital') {
					this.filterConditions.hospital = {
						province: this.selectedProvince,
						city: this.selectedCity,
						district: this.selectedDistrict,
						level: this.selectedLevel,
						type: this.selectedType,
					}
					this.filterHospitals()
				}
				this.hideFilter()
			},
			filterHospitals() {
			    console.log('筛选条件：', this.filterConditions.hospital);
			    const { province, city, level, type } = this.filterConditions.hospital;
			    this.filteredHospitals = this.hospitals.filter(hospital => {
			        const matchesProvince = province ? hospital.address.province === province : true;
			        const matchesCity = city ? hospital.address.city === city : true;
			        const matchesLevel = level ? hospital.level === level : true;
			        const matchesType = type ? hospital.type === type : true;
			        return matchesProvince && matchesCity && matchesLevel && matchesType;
			    });
			},
			selectProvince(province) {
				if (this.selectedProvince === province) {
					this.selectedProvince = ''
					//this.filterConditions.hospital.province = province
					this.selectedCity = ''
					this.selectedDistrict = ''
				} else {
					this.selectedProvince = province
					this.selectedCity = ''
					this.selectedDistrict = ''
				}
			},
			selectCity(city) {
				if (this.selectedCity === city) {
					this.selectedCity = ''
					//this.filterConditions.hospital.city = city
					this.selectedDistrict = ''
				} else {
					this.selectedCity = city
					this.selectedDistrict = ''
				}
			},
			//selectDistrict(district) {
			//	this.selectedDistrict = this.selectedDistrict === district ? '' : district
			//},
			    // 获取医院列表数据
			    async getHospitalList() {
			      try {
			        uni.showLoading({ title: '加载中...' });
			        const res = await uniCloud.callFunction({
			          name: 'getHospitals',
			          data: {
			            page: 1,
			            pageSize: 999
			          }
			        });
			        console.log("获取到的医院列表数据：", res); // 调试信息
			        if (res.result.code === 0) {
			          this.hospitals = res.result.data.list;
			          this.filteredHospitals = [...this.hospitals];
			        } else {
			          uni.showToast({
			            title: `获取数据失败：${res.result.msg}`,
			            icon: 'none'
			          });
			        }
			      } catch (e) {
			        uni.showToast({
			          title: '获取医院列表失败',
			          icon: 'none'
			        });
			        console.error("获取医院列表失败：", e);
			      } finally {
			        uni.hideLoading();
			      }
			    },
			// 处理医院列表点击事件
			handleHospitalTap(hospital) {
							if (this.fromPage === 'index') {
								// 如果从 index 页面进入，跳转到医院官网
								if (!hospital.website || hospital.website === "") {
									uni.showToast({
										title: '暂无医院官网信息',
										icon: 'none',
										duration: 2000
									});
									return;
								}
								try {
									let url = hospital.website;
									if (!url.startsWith('http://') && !url.startsWith('https://')) {
										url = 'http://' + url;
									}
			
									// 使用微信小程序的API打开网页
									uni.navigateTo({
										url: `/pages/web-view/web-view?url=${encodeURIComponent(url)}`,
										fail: (err) => {
											console.error('跳转失败:', err);
											uni.showToast({
												title: '打开网页失败',
												icon: 'none'
											});
										}
									});
								} catch (error) {
									console.error('打开网页错误:', error);
									uni.showToast({
										title: '打开网页失败',
										icon: 'none'
									});
								}
							} else {
								// 如果从其他页面进入，返回数据到上一页
								uni.navigateBack({
									delta: 1,
									success: () => {
										uni.$emit('select-hospital', hospital) // 发送事件到上一页
									}
								})
							}
			},
			//监视页面滚动情况
			handleScroll(e) {
				// 直接赋值scrollTop（不需要节流，因为custom-nav内部已经做了立即切换的处理）
				this.scrollTop = e.detail.scrollTop;
				console.log("scrollTop")
			},
						},
	
		onLoad(options) {
			// 获取导航栏高度
			const systemInfo = uni.getSystemInfoSync();
			this.navHeight = systemInfo.statusBarHeight + 44;
			// 获取页面来源信息
			this.fromPage = options.from || null
			this.getHospitalList() // 页面加载时获取数据
		},
		
	}
</script>

