		position: fixed;
		top: 180rpx;
		left: 0;
		right: 0;
		z-index: 100;
		box-sizing: border-box;
	}

	.search-box {
		flex: 1;
		height: 70rpx;
		margin-right: 20rpx;
		position: relative;
	}

	.search-input {
		width: 100%;
		height: 70rpx;
