		overflow: hidden;
	}

	.hospital-card image {
		width: 100%;
		height: 200rpx;
		text-align: center;
	}

	.hospital-info {
		padding: 20rpx;
	}

	.hospital-name {
		display: block;
		font-size: 28rpx;
		font-weight: bold;
		color: #333;
		margin-bottom: 10rpx;
	}

    .type-level-container {
        display: flex;
        align-items: center;
        margin-bottom: 10rpx;
    }
    
    .hospital-level {
        font-size: 24rpx;
        color: #02D4C6;
        margin-right: 10rpx; /* 添加间隔 */
    }
    
    .hospital-type {
        font-size: 24rpx;
        color: #02D4C6;
    }

	.hospital-address {
		display: block;
		font-size: 24rpx;
		color: #999;
	}

	/* 疾病列表样式 */
	.disease-content {
		width: 100%;
		margin-top: 120rpx;
		display: flex;
		height: calc(100vh - 120rpx);
	}

	.disease-categories {
		width: 200rpx;
		background-color: #f5f5f5;
		height: 100%;
	}

	.category-item {
		width: 100%;
		height: 90rpx;
		line-height: 90rpx;
		font-size: 28rpx;
		color: #666;
		text-align: center;
		border-left: 6rpx solid transparent;
		box-sizing: border-box;
	}

	.category-item.active {
		color: #02D4C6;
		background-color: #ffffff;
		border-left-color: #02D4C6;
	}

	.disease-list {
		flex: 1;
		background-color: #ffffff;
		height: 100%;
	}

	.disease-item {
		width: 100%;
		height: 90rpx;
		line-height: 90rpx;
		padding: 0 30rpx;
		font-size: 28rpx;
		color: #333;
		border-bottom: 1rpx solid #eee;
		box-sizing: border-box;
	}

	.filter-btn {
		position: absolute;
		left: 20rpx;
		top: 50%;
		transform: translateY(-50%);
		display: flex;
		align-items: center;
		z-index: 1;
	}

	.filter-text {
		font-size: 28rpx;
		color: #666;
		margin-right: 6rpx;
	}

	.filter-icon {
		font-size: 24rpx;
		color: #666;
	}

	.filter-mask {
		position: fixed;
		top: 0;
		left: 0;
		right: 0;
		bottom: 0;
		background-color: rgba(0, 0, 0, 0.5);
		z-index: 999;
	}

	.filter-panel {
		position: absolute;
		top: 0;
		left: 0;
		width: 85%;
		height: 100%;
		background-color: #fff;
		padding: 40rpx 30rpx;
		box-sizing: border-box;
	}

	.filter-header {
		display: flex;
		justify-content: space-between;
		align-items: center;
		padding-bottom: 30rpx;
		border-bottom: 1rpx solid #eee;
	}

	.close-btn {
		font-size: 40rpx;
		color: #999;
		padding: 10rpx;
	}

	.filter-section {
		margin-top: 30rpx;
	}

	.section-title {
		font-size: 30rpx;
		font-weight: 500;
		color: #333;
		margin-bottom: 24rpx;
	}

	.filter-options {
		display: flex;
		flex-wrap: wrap;
		gap: 20rpx;
	}

	.filter-option {
		padding: 10rpx 30rpx;
		border-radius: 30rpx;
