	}

	.filter-option.active {
		background-color: #02D4C6;
		color: #fff;
	}

	.filter-buttons {
		position: absolute;
		bottom: 30rpx;
		left: 30rpx;
		right: 30rpx;
		display: flex;
		gap: 20rpx;
	}

	.reset-btn,
	.confirm-btn {
		flex: 1;
		height: 80rpx;
		line-height: 80rpx;
