		border-radius: 40rpx;
		font-size: 28rpx;
	}

	.reset-btn {
		background-color: #f5f5f5;
		color: #666;
	}

	.confirm-btn {
		background-color: #02D4C6;
		color: #fff;
	}

	.location-section {
		margin-bottom: 40rpx;
	}

	.location-container {
		display: flex;
